-- discharge_into_water_body
update public.fields set verification_status='verified_against_standard', verification_quote='According to the Federal Water Act (WHG), the discharge of treated greywater implies the use of a water body and therefore, it requires an official permit in compliance with § 8 of the WHG. This permit required under water law grants a revocable right and, if necessary, limited authority to use the water body (WHG 2009). | For the discharge of treated greywater into a receiving water body or for infiltration purposes, the requirements need to be coordinated with the responsible approval authorities. The general requirements according to AbwV Annex 1 can serve as a basis. In individual cases, additional requirements can be placed by the responsible supervisory authority (see Section 4.3). — printed p.13 / p.21', verification_note='md-verified 2026-09-05 (§4.3 Water Law; §6.4, printed p.13 / p.21 derived) [VC]', verified_at=now() where id='01b2efc0-a382-4683-ad7d-3e66d7f7d700' and verification_status not in ('verified_against_standard','corrected');
-- treats_greywater
update public.fields set verification_status='verified_against_standard', verification_quote='The Guideline DWA-M 277 can be applied to systems which process and supply service water from greywater for private as well as public/commercial buildings, or which treat the greywater and drain it. | Systems, which do not treat the generated greywater, are not covered by this document. — printed p.7', verification_note='md-verified 2026-09-05 (§1 Scope, printed p.7 derived) [VC]', verified_at=now() where id='77830914-1af8-4c1c-bbd0-6d00288c8d3a' and verification_status not in ('verified_against_standard','corrected');
