-- source_set
update public.fields set verification_status='verified_against_standard', verification_quote='Due to its source of origin (drains from hand washbasins, showers, washing machines and where applicable kitchen wastewater), greywater, compared to the other separated flows (lyellow and blackwater), or to the unseparated household wastewater, is poor in nutrients such as phosphorous and nitrogen and exhibits only half of the organic pollution load measured as chemical or biological oxygen demand (Table 1). In the present document, data from Sievers et al. (2014) are recommended as design values. | Table 2: Quality of seperated greywater flows from different sources of origin (Source: DWA 2008; KEYSERS 2007; fbr 2005). | & Shower & Bathtub & Hand washbasin & Washing machine & Kitchen sink & Dish washer — printed p.15 / p.16', verification_note='md-verified 2026-09-05 (§5; Table 2 header, printed p.15 / p.16 derived) [VC]', verified_at=now() where id='716dd811-c30f-4a3a-8597-0220ba1867a0' and verification_status not in ('verified_against_standard','corrected');
-- greywater_type
update public.fields set verification_status='verified_against_standard', verification_quote='Therefore, within the scope of this document a distinction is made between two types of greywater (Table 2): | Type A: low grade greywater, i.e. greywater excluding drains from kitchen and washing machines - Type A1: greywater from bathtubs and showers - Type A2: greywater from bathtubs, showers and hand washbasins | Type B: high grade greywater, i.e. greywater from kitchen drains and/or washing machines - Type B1: greywater from bathtubs, showers, hand washbasins and washing machines - Type B2: greywater from bathtubs, showers, hand washbasins, washing machines and/or kitchen. — printed p.15', verification_note='md-verified 2026-09-05 (§5, printed p.15 derived) [VC]', verified_at=now() where id='beb5e012-2353-4d05-939b-22196a12edfe' and verification_status not in ('verified_against_standard','corrected');

