-- attest_m277e_03_req_24
update public.fields set verification_status='verified_against_standard', verification_quote='Quality requirements for irrigation water are regulated by DIN 19650. These quality requirements address hygienic/microbiological concerns of irrigation water in agriculture, horticulture, landscaping as well as in parks and sports facilities. The hygienic safety is subdivided into four suitability classes, each of which must be verified depending on the intended use (see DIN 19650: Table 4). | The application of standards according to DIN 19650 is recommended for private households. Treatment of the greywater by means of a suitable technology is indispensable. — printed p.19', verification_note='md-verified 2026-09-05 (§6.2.4, printed p.19 derived) [VC] — attestation checkbox for REQ-24; clause_reference is empty in prod — STAGED S-7 retag §6.2.4; the obligation applies to irrigation use only', verified_at=now() where id='0aca622b-2506-49d4-b0e6-0f9bc12c1ea6' and verification_status not in ('verified_against_standard','corrected');

-- ######################## M277E-04 · Rechtsrahmen Uebersicht (IfSG, TrinkwV, WHG, MBO) ########################
-- quality_category
update public.fields set verification_status='verified_against_standard', verification_quote='The quality requirements for service water are subdivided in Section 6.3 into two categories, C1 and C2 and are defined in Table 4 (see Section 6.3). | C1: mechanical, biological treatment and stabilization of greywater of the Type A Characterisation: storage and aeration for reuse as toilet flush water in private sector | C2: mechanical, biological treatment and hygienisation of greywater of the Type A and Type B Characterisation: storage and treatment for reuse in private and public sectors. | Table 4: Quality requirements for treated greywater and the treatment processes | Use category & C1 & C2 | Treatment/Stabilisation & Treatment and hygienisation — printed p.18 / p.19', verification_note='md-verified 2026-09-05 (§6.1; §6.3; Table 4, printed p.18 / p.19 derived) [VC]', verified_at=now() where id='1bc09def-fd6f-443c-a5a6-84803736fc34' and verification_status not in ('verified_against_standard','corrected');
-- use_category
