-- DIN_19650_class_documented
update public.fields set verification_status='verified_against_standard', verification_quote='Quality requirements for irrigation water are regulated by DIN 19650. These quality requirements address hygienic/microbiological concerns of irrigation water in agriculture, horticulture, landscaping as well as in parks and sports facilities. The hygienic safety is subdivided into four suitability classes, each of which must be verified depending on the intended use (see DIN 19650: Table 4). — printed p.19', verification_note='md-verified 2026-09-05 (§6.2.4, printed p.19 derived) [VC] — DIN 19650 itself is not in the library — the class list is NR; the field records only that the class was verified', verified_at=now() where id='4b773b16-8544-4882-a38d-3048f854bab4' and verification_status not in ('verified_against_standard','corrected');
-- discharge_into_water_body
update public.fields set verification_status='verified_against_standard', verification_quote='According to the Federal Water Act (WHG), the discharge of treated greywater implies the use of a water body and therefore, it requires an official permit in compliance with § 8 of the WHG. This permit required under water law grants a revocable right and, if necessary, limited authority to use the water body (WHG 2009). | For the discharge of treated greywater into a receiving water body or for infiltration purposes, the requirements need to be coordinated with the responsible approval authorities. The general requirements according to AbwV Annex 1 can serve as a basis. In individual cases, additional requirements can be placed by the responsible supervisory authority (see Section 4.3). — printed p.13 / p.21', verification_note='md-verified 2026-09-05 (§4.3 Water Law; §6.4, printed p.13 / p.21 derived) [VC] — duplicate of the ws 01 field of the same symbol', verified_at=now() where id='eadcedbb-1f92-408c-b86c-5e254024cef4' and verification_status not in ('verified_against_standard','corrected');

