-- ######################## M277E-06 · Grauwasser-Quellenklassifikation (Typ A/B) ########################
-- source_set
update public.fields set verification_status='verified_against_standard', verification_quote='Due to its source of origin (drains from hand washbasins, showers, washing machines and where applicable kitchen wastewater), greywater, compared to the other separated flows (lyellow and blackwater), or to the unseparated household wastewater, is poor in nutrients such as phosphorous and nitrogen and exhibits only half of the organic pollution load measured as chemical or biological oxygen demand (Table 1). In the present document, data from Sievers et al. (2014) are recommended as design values. | Table 2: Quality of seperated greywater flows from different sources of origin (Source: DWA 2008; KEYSERS 2007; fbr 2005). | & Shower & Bathtub & Hand washbasin & Washing machine & Kitchen sink & Dish washer — printed p.15 / p.16', verification_note='md-verified 2026-09-05 (§5; Table 2 header, printed p.15 / p.16 derived) [VC] — duplicate of the ws 02 field', verified_at=now() where id='249bdb57-8eeb-4c1f-855d-f213e4494e5e' and verification_status not in ('verified_against_standard','corrected');
-- Q_SW
update public.fields set verification_status='verified_against_standard', verification_quote='$\mathrm{Q}_{\mathrm{SW}}$ & l/d & Total service water demand | The daily total service water demand $\left(\mathrm{Q}_{\mathrm{SW}}\right)$ can be calculated from the subtotals of the single application areas according to the following formula: | Q_{S W}=\Sigma\left(Q_{S W-P, i} \cdot P_{i}\right)+\Sigma\left(Q_{S W-A, j} \cdot A_{j}\right) \tag{1} — printed p.10 / p.25', verification_note='md-verified 2026-09-05 (§2.2 Symbols; §9.2 Eq.(1), printed p.10 / p.25 derived) [VC] — derived — Eq.(1) output', verified_at=now() where id='0ef42fac-9686-4ee3-9c26-d0c6d4009250' and verification_status not in ('verified_against_standard','corrected');
-- greywater_type
update public.fields set verification_status='verified_against_standard', verification_quote='Therefore, within the scope of this document a distinction is made between two types of greywater (Table 2): | Type A: low grade greywater, i.e. greywater excluding drains from kitchen and washing machines - Type A1: greywater from bathtubs and showers - Type A2: greywater from bathtubs, showers and hand washbasins | Type B: high grade greywater, i.e. greywater from kitchen drains and/or washing machines - Type B1: greywater from bathtubs, showers, hand washbasins and washing machines - Type B2: greywater from bathtubs, showers, hand washbasins, washing machines and/or kitchen. — printed p.15', verification_note='md-verified 2026-09-05 (§5, printed p.15 derived) [VC] — duplicate of the ws 02 field', verified_at=now() where id='6b91caa7-b7f0-40ff-af99-630defe09d07' and verification_status not in ('verified_against_standard','corrected');

