update public.fields set verification_status='verified_against_standard', verification_quote='Greywater reuse systems must be provided with an automatic water backfeed system. For this purpose, drinking water, rainwater or other water source of suitable quality can be used. For greywater treatment with the sole purpose of disposal this is not required. For the reuse of the treated greywater solely outside the building, the automatic mode of the backfeed system is not required in some cases. | Backfeed supply | A setup for the additional supply of potable water to the greywater reuse system. — printed p.23 / p.9', verification_note='md-verified 2026-09-05 (§7.2; §2.1 Backfeed supply, printed p.23 / p.9 derived) [VC] — "must" — but the same paragraph exempts disposal-only treatment and (in some cases) outdoor-only reuse; REQ-12 is unconditional — STAGED S-3', verified_at=now() where id='ee40fa7a-935b-4dfa-9f23-45b9f6057966' and verification_status not in ('verified_against_standard','corrected');
-- network_separation_per_DIN_EN_1717
update public.fields set verification_status='verified_against_standard', verification_quote='For the installation of the drinking water backfeed system, the user is referred to DIN 1989-1: "Rainwater harvesting systems - Part 1: Planning, installation, operation and maintenance". Here, information on the installation of the backfeed system using drinking water should be taken into consideration. To carry out the network separation, reference is made to DIN EN 1717. | Protection facility | Technical facility for drinking water protection in accordance with DIN EN 1717:2011. — printed p.23 / p.9', verification_note='md-verified 2026-09-05 (§7.2; §2.1 Protection facility, printed p.23 / p.9 derived) [VC] — DIN EN 1717 itself is NR (not in library); the guideline references it', verified_at=now() where id='85341645-4ea2-4c5a-b5fd-397a71f80e07' and verification_status not in ('verified_against_standard','corrected');
-- service_water_labelled
update public.fields set verification_status='verified_against_standard', verification_quote='In order to safely and permanently exclude any contamination of the drinking water, the legal requirements in compliance with § 17 Para. 6 of the Drinking Water Ordinance (TrinkwV) apply to the pipework of rainwater and greywater reuse systems, inter alia. Service water reuse systems should have no connection with the drinking water supply systems and should be colour-coded. Service water collection points must be permanently labelled as such. It should be safeguarded through appropriate technical facilities, that no greywater from the greywater reuse system will enter the drinking water network (also not during a pressure drop in the drinking water pipe). — printed p.14', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 17 Para. 6), printed p.14 derived) [VC] — colour-coding is "should", permanent labelling of collection points is "must"', verified_at=now() where id='578fd7a9-6940-4d53-a5b4-5a65ac2b1107' and verification_status not in ('verified_against_standard','corrected');
-- installation_frost_free
update public.fields set verification_status='verified_against_standard', verification_quote='A trouble-free operation is only secured in a frost-free installation. Depending on the type of technology used, storage of the greywater should be provided for before and/or after treatment. It is recommended that the total buffer volume corresponds to one-day treatment capacity. — printed p.22', verification_note='md-verified 2026-09-05 (§7.1, printed p.22 derived) [VC] — descriptive sentence ("only secured in a frost-free installation"), no modal verb', verified_at=now() where id='401ec88c-84ad-4727-9a3f-74a3294afd42' and verification_status not in ('verified_against_standard','corrected');
-- auto_switch_to_backfeed
update public.fields set verification_status='verified_against_standard', verification_quote='In the event of failure of the service water supply it is recommended to switch automatically to the water backfeed system. The failure should be reported automatically. The operator or a person instructed by him must ensure for an operation in accordance with the regulations. The system must be operated according to the manufacturer''s specifications. — printed p.24', verification_note='md-verified 2026-09-05 (§8, printed p.24 derived) [VC] — "recommended" — is_required=true and REQ-21-2 block over-state the source — STAGED S-5/S-8', verified_at=now() where id='f1801db9-bc32-46ab-a1b6-9a1a08b9e554' and verification_status not in ('verified_against_standard','corrected');
-- auto_fault_report
update public.fields set verification_status='verified_against_standard', verification_quote='In the event of failure of the service water supply it is recommended to switch automatically to the water backfeed system. The failure should be reported automatically. The operator or a person instructed by him must ensure for an operation in accordance with the regulations. The system must be operated according to the manufacturer''s specifications. — printed p.24', verification_note='md-verified 2026-09-05 (§8, printed p.24 derived) [VC] — "should be reported automatically" — is_required=true and REQ-21-2 block over-state the source — STAGED S-5/S-8', verified_at=now() where id='af1303a2-2db9-4782-b277-4fc3f2f2467b' and verification_status not in ('verified_against_standard','corrected');
-- drinking_water_option_available
update public.fields set verification_status='verified_against_standard', verification_quote='For service water reuse in laundry and (subordinate) in the building cleaning services (e.g. floor and terrace cleaning) in the private sector, the quality requirements und recommendations described in Table 4 can be also applied. In rented apartments the user must also have the possibility to use drinking water for these purposes (BVerwG Az. 8 C 41.09, 2010). — printed p.18', verification_note='md-verified 2026-09-05 (§6.2.2 (BVerwG Az. 8 C 41.09), printed p.18 derived) [VC] — "must" applies to rented apartments and to laundry/cleaning use ("these purposes")', verified_at=now() where id='f2043af2-25c9-49fe-a761-78dccb9cb44c' and verification_status not in ('verified_against_standard','corrected');
-- service_water_isolated_from_drinking_water
update public.fields set verification_status='verified_against_standard', verification_quote='In order to safely and permanently exclude any contamination of the drinking water, the legal requirements in compliance with § 17 Para. 6 of the Drinking Water Ordinance (TrinkwV) apply to the pipework of rainwater and greywater reuse systems, inter alia. Service water reuse systems should have no connection with the drinking water supply systems and should be colour-coded. Service water collection points must be permanently labelled as such. It should be safeguarded through appropriate technical facilities, that no greywater from the greywater reuse system will enter the drinking water network (also not during a pressure drop in the drinking water pipe). | The operator must ensure through suitable measures that the system has no repercussions on the drinking water network. — printed p.14', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 17 Para. 6), printed p.14 derived) [VC]', verified_at=now() where id='740dfa2a-b85c-4955-bddd-663fb400085c' and verification_status not in ('verified_against_standard','corrected');
