-- DIN_19650_class_documented
update public.fields set verification_status='verified_against_standard', verification_quote='Quality requirements for irrigation water are regulated by DIN 19650. These quality requirements address hygienic/microbiological concerns of irrigation water in agriculture, horticulture, landscaping as well as in parks and sports facilities. The hygienic safety is subdivided into four suitability classes, each of which must be verified depending on the intended use (see DIN 19650: Table 4). — printed p.19', verification_note='md-verified 2026-09-05 (§6.2.4, printed p.19 derived) [VC] — duplicate of ws 04; DIN 19650 is NR', verified_at=now() where id='d66d600a-b386-4e91-b58f-4a9b51e7e933' and verification_status not in ('verified_against_standard','corrected');
-- WHG_permit_present
update public.fields set verification_status='verified_against_standard', verification_quote='According to the Federal Water Act (WHG), the discharge of treated greywater implies the use of a water body and therefore, it requires an official permit in compliance with § 8 of the WHG. This permit required under water law grants a revocable right and, if necessary, limited authority to use the water body (WHG 2009). — printed p.13', verification_note='md-verified 2026-09-05 (§4.3 Water Law (WHG § 8), printed p.13 derived) [VC]', verified_at=now() where id='547142c8-8c70-469f-b244-723442621d65' and verification_status not in ('verified_against_standard','corrected');
-- owner_or_user_change
update public.fields set verification_status='verified_against_standard', verification_quote='Furthermore, attention should be paid to § 13 Para. 4 of the Drinking Water Ordinance (TrinkwV), which implies that owners of rainwater and greywater treatment/reuse systems are obliged to notify the health authority upon commissioning. If these systems are already in operation, notification should be made immediately. In addition, recommissioning of systems which have undergone constructional or operational changes or user/owner change as well as system shutdown are also notifiable. — printed p.14', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 13 Para. 4), printed p.14 derived) [VC]', verified_at=now() where id='44e4445c-7754-464c-a212-8ace51350ee7' and verification_status not in ('verified_against_standard','corrected');
-- authority_notification_sent
update public.fields set verification_status='verified_against_standard', verification_quote='Furthermore, attention should be paid to § 13 Para. 4 of the Drinking Water Ordinance (TrinkwV), which implies that owners of rainwater and greywater treatment/reuse systems are obliged to notify the health authority upon commissioning. If these systems are already in operation, notification should be made immediately. In addition, recommissioning of systems which have undergone constructional or operational changes or user/owner change as well as system shutdown are also notifiable. | The operation and start-up of a greywater reuse system should be reported to the responsible authority in accordance with the guidelines of the Drinking Water Ordinance. — printed p.14 / p.24', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 13 Para. 4); §8, printed p.14 / p.24 derived) [VC]', verified_at=now() where id='b69377af-18f1-40a6-a789-7ed1e15410b4' and verification_status not in ('verified_against_standard','corrected');
