-- treatment_indispensable_ack
update public.fields set verification_status='verified_against_standard', verification_quote='In public and commercial buildings and there, where several households are connected to a greywater reuse system, treatment of the greywater depending on the intended use and the corresponding quality requirements, is indispensable. For the private sector, appropriate treatment processes should also be provided for greywater reuse. Quality requirements for service water should be orientated towards the specific intended use. | If reuse of the treated greywater is planned, it is necessary that it undergoes biological stabilisation and disinfection. — printed p.18 / p.11', verification_note='md-verified 2026-09-05 (§6.1; §3, printed p.18 / p.11 derived) [VC]', verified_at=now() where id='b23e3ae7-ffc1-4dc1-94f8-f5ccd12a6830' and verification_status not in ('verified_against_standard','corrected');

