-- irrigation_season_length
update public.fields set verification_status='verified_against_standard', verification_quote='Example calculation Part 1: Service water demand | Building object: household | Residents: 25 P | Service water consumers: toilets, irrigation of kitchen garden ( $150 \mathrm{~m}^{2}$, season with 180 days) | Q_{S W}=25 \mathrm{P} \cdot 33 \mathrm{l} /(\mathrm{P} \cdot \mathrm{~d}) \text { toilet }+60 \mathrm{l} / \mathrm{m}^{2} \cdot 150 \mathrm{~m}^{2} / 180 \mathrm{~d} \text { kitchen garden } | Q_{S W}=875 \mathrm{l} / \mathrm{d} | Minimum service water quality: C2 due to the irrigation of the kitchen garden. — printed p.25', verification_note='md-verified 2026-09-05 (§9.2 Example calculation Part 1, printed p.25 derived) [VC] — engineer_input: the source prints "season with 180 days" only inside the worked example (kitchen garden); no rule or range', verified_at=now() where id='946405f9-78b8-4985-8f73-bdcae94891e3' and verification_status not in ('verified_against_standard','corrected');

