-- Q_SW
update public.fields set verification_status='verified_against_standard', verification_quote='$\mathrm{Q}_{\mathrm{SW}}$ & l/d & Total service water demand | The daily total service water demand $\left(\mathrm{Q}_{\mathrm{SW}}\right)$ can be calculated from the subtotals of the single application areas according to the following formula: | Q_{S W}=\Sigma\left(Q_{S W-P, i} \cdot P_{i}\right)+\Sigma\left(Q_{S W-A, j} \cdot A_{j}\right) \tag{1} — printed p.10 / p.25', verification_note='md-verified 2026-09-05 (§2.2 Symbols; §9.2 Eq.(1), printed p.10 / p.25 derived) [VC] — duplicate of ws 06; derived — Eq.(1) output', verified_at=now() where id='6389d32a-6b7c-4f51-a186-04ea2d38331f' and verification_status not in ('verified_against_standard','corrected');

