-- automatic_backfeed_present
update public.fields set verification_status='verified_against_standard', verification_quote='Greywater reuse systems must be provided with an automatic water backfeed system. For this purpose, drinking water, rainwater or other water source of suitable quality can be used. For greywater treatment with the sole purpose of disposal this is not required. For the reuse of the treated greywater solely outside the building, the automatic mode of the backfeed system is not required in some cases. | Backfeed supply | A setup for the additional supply of potable water to the greywater reuse system. — printed p.23 / p.9', verification_note='md-verified 2026-09-05 (§7.2; §2.1 Backfeed supply, printed p.23 / p.9 derived) [VC] — duplicate of ws 09; disposal-only exemption — STAGED S-3', verified_at=now() where id='a199f53f-6158-4f0c-a946-5c6e7fd619c9' and verification_status not in ('verified_against_standard','corrected');
-- network_separation_per_DIN_EN_1717
update public.fields set verification_status='verified_against_standard', verification_quote='For the installation of the drinking water backfeed system, the user is referred to DIN 1989-1: "Rainwater harvesting systems - Part 1: Planning, installation, operation and maintenance". Here, information on the installation of the backfeed system using drinking water should be taken into consideration. To carry out the network separation, reference is made to DIN EN 1717. | Protection facility | Technical facility for drinking water protection in accordance with DIN EN 1717:2011. — printed p.23 / p.9', verification_note='md-verified 2026-09-05 (§7.2; §2.1 Protection facility, printed p.23 / p.9 derived) [VC] — duplicate of ws 09; DIN EN 1717 is NR', verified_at=now() where id='260065db-bdf0-4990-9149-0b12f47a1063' and verification_status not in ('verified_against_standard','corrected');
-- service_water_labelled
update public.fields set verification_status='verified_against_standard', verification_quote='In order to safely and permanently exclude any contamination of the drinking water, the legal requirements in compliance with § 17 Para. 6 of the Drinking Water Ordinance (TrinkwV) apply to the pipework of rainwater and greywater reuse systems, inter alia. Service water reuse systems should have no connection with the drinking water supply systems and should be colour-coded. Service water collection points must be permanently labelled as such. It should be safeguarded through appropriate technical facilities, that no greywater from the greywater reuse system will enter the drinking water network (also not during a pressure drop in the drinking water pipe). — printed p.14', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 17 Para. 6), printed p.14 derived) [VC] — duplicate of ws 09', verified_at=now() where id='99e14045-e431-4874-b983-50c1eeb6c55b' and verification_status not in ('verified_against_standard','corrected');
-- service_water_isolated_from_drinking_water
update public.fields set verification_status='verified_against_standard', verification_quote='In order to safely and permanently exclude any contamination of the drinking water, the legal requirements in compliance with § 17 Para. 6 of the Drinking Water Ordinance (TrinkwV) apply to the pipework of rainwater and greywater reuse systems, inter alia. Service water reuse systems should have no connection with the drinking water supply systems and should be colour-coded. Service water collection points must be permanently labelled as such. It should be safeguarded through appropriate technical facilities, that no greywater from the greywater reuse system will enter the drinking water network (also not during a pressure drop in the drinking water pipe). | The operator must ensure through suitable measures that the system has no repercussions on the drinking water network. — printed p.14', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 17 Para. 6), printed p.14 derived) [VC] — duplicate of ws 09', verified_at=now() where id='aedc6085-dd42-4ead-8921-5cbbaae3f6ab' and verification_status not in ('verified_against_standard','corrected');
