-- backfeed_source
update public.fields set verification_status='verified_against_standard', verification_quote='Greywater reuse systems must be provided with an automatic water backfeed system. For this purpose, drinking water, rainwater or other water source of suitable quality can be used. For greywater treatment with the sole purpose of disposal this is not required. For the reuse of the treated greywater solely outside the building, the automatic mode of the backfeed system is not required in some cases. — printed p.23', verification_note='md-verified 2026-09-05 (§7.2, printed p.23 derived) [VC] — tokens drinking_water / rainwater / other = "drinking water, rainwater or other water source of suitable quality"', verified_at=now() where id='dd326b88-681f-400c-8a68-8ecc05da6541' and verification_status not in ('verified_against_standard','corrected');
-- backfeed_switch_on_level
update public.fields set verification_status='verified_against_standard', verification_quote='The switch-on point of the backfeed system and the required volume flow of the water backfeed should be dimensioned in a way, that the service water pumps do not run dry, in case of a breakdown of the greywater treatment system. — printed p.23', verification_note='md-verified 2026-09-05 (§7.2, printed p.23 derived) [VC] — the source names the switch-on point without a unit or value; the encoded unit (l, tank content) is EKOWAI''s', verified_at=now() where id='cb9b0870-0fa5-495a-94c1-d7324bfc7f28' and verification_status not in ('verified_against_standard','corrected');
