-- tapping_points_labelled
update public.fields set verification_status='verified_against_standard', verification_quote='In order to safely and permanently exclude any contamination of the drinking water, the legal requirements in compliance with § 17 Para. 6 of the Drinking Water Ordinance (TrinkwV) apply to the pipework of rainwater and greywater reuse systems, inter alia. Service water reuse systems should have no connection with the drinking water supply systems and should be colour-coded. Service water collection points must be permanently labelled as such. It should be safeguarded through appropriate technical facilities, that no greywater from the greywater reuse system will enter the drinking water network (also not during a pressure drop in the drinking water pipe). — printed p.14', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 17 Para. 6), printed p.14 derived) [VC] — clause_reference reads §7.3, the "must be permanently labelled" sentence is §4.4 — STAGED S-7 retag; the wording "Kein Trinkwasser" in the label is not in the source', verified_at=now() where id='04bed99c-38af-4947-a928-558512f0548e' and verification_status not in ('verified_against_standard','corrected');
-- colour_coding_applied
update public.fields set verification_status='verified_against_standard', verification_quote='In order to safely and permanently exclude any contamination of the drinking water, the legal requirements in compliance with § 17 Para. 6 of the Drinking Water Ordinance (TrinkwV) apply to the pipework of rainwater and greywater reuse systems, inter alia. Service water reuse systems should have no connection with the drinking water supply systems and should be colour-coded. Service water collection points must be permanently labelled as such. It should be safeguarded through appropriate technical facilities, that no greywater from the greywater reuse system will enter the drinking water network (also not during a pressure drop in the drinking water pipe). — printed p.14', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 17 Para. 6), printed p.14 derived) [VC] — clause_reference reads §7.3, the "should be colour-coded" sentence is §4.4 — STAGED S-7 retag; the colour "grün" in the label is NOT printed anywhere in DWA-M 277E', verified_at=now() where id='79e4d9ed-49bb-490d-850d-fa71421d7a96' and verification_status not in ('verified_against_standard','corrected');
-- control_panel_included
update public.fields set verification_status='verified_against_standard', verification_quote='Control panel | Control system for the automatic operation of greywater treatment and reuse systems. | In the event of failure of the service water supply it is recommended to switch automatically to the water backfeed system. The failure should be reported automatically. The operator or a person instructed by him must ensure for an operation in accordance with the regulations. The system must be operated according to the manufacturer''s specifications. — printed p.9 / p.24', verification_note='md-verified 2026-09-05 (§2.1 Control panel; §8, printed p.9 / p.24 derived) [VC] — clause_reference reads §8; the definition is §2.1 — STAGED S-7 retag', verified_at=now() where id='b63122d9-91f3-4645-9de8-3c2c81806489' and verification_status not in ('verified_against_standard','corrected');
