-- owner_or_user_change
update public.fields set verification_status='verified_against_standard', verification_quote='Furthermore, attention should be paid to § 13 Para. 4 of the Drinking Water Ordinance (TrinkwV), which implies that owners of rainwater and greywater treatment/reuse systems are obliged to notify the health authority upon commissioning. If these systems are already in operation, notification should be made immediately. In addition, recommissioning of systems which have undergone constructional or operational changes or user/owner change as well as system shutdown are also notifiable. — printed p.14', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 13 Para. 4), printed p.14 derived) [VC] — duplicate of ws 11', verified_at=now() where id='29ebe9cd-c157-4d6b-98bc-114acdda737e' and verification_status not in ('verified_against_standard','corrected');
