update public.fields set verification_status='verified_against_standard', verification_quote='Furthermore, attention should be paid to § 13 Para. 4 of the Drinking Water Ordinance (TrinkwV), which implies that owners of rainwater and greywater treatment/reuse systems are obliged to notify the health authority upon commissioning. If these systems are already in operation, notification should be made immediately. In addition, recommissioning of systems which have undergone constructional or operational changes or user/owner change as well as system shutdown are also notifiable. | The operation and start-up of a greywater reuse system should be reported to the responsible authority in accordance with the guidelines of the Drinking Water Ordinance. — printed p.14 / p.24', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 13 Para. 4); §8, printed p.14 / p.24 derived) [VC] — duplicate of ws 11; same-worksheet duplicate of health_authority_notified — STAGED S-9', verified_at=now() where id='1621cc40-2efe-4429-9d3c-0ffe6e28d2cd' and verification_status not in ('verified_against_standard','corrected');
