-- ce_conformity_present
update public.fields set verification_status='verified_against_standard', verification_quote='To generate a conformity certificate and a CE-label, further requirements which arise from other European rules and standards such as the Machinery Directive (Directive 2006/42/EG), the Low-Voltage Directive (Directive 2014/35/EU) or the EMC Directive (Directive 2014/30/EU) (electromagnetic compatibility) must be identified and implemented. | The basic requirements of the Construction Products Regulation are valid for construction products, which may be marketed only, if they are usable (Regulation (EU) No 305/2011, Para. 41). — printed p.13 / p.13', verification_note='md-verified 2026-09-05 (§4.1; §4.2 Construction Products Regulation, printed p.13 / p.13 derived) [VC] — the CE-label sentence is §4.1 (Machinery/Low-Voltage/EMC Directives); §4.2 covers CPR usability — the label conflates the two; clause_reference §4.2 → §4.1/§4.2 — STAGED S-7', verified_at=now() where id='21a51124-a2d4-40b2-8d89-25230cb4d4f9' and verification_status not in ('verified_against_standard','corrected');
-- health_authority_notified
update public.fields set verification_status='verified_against_standard', verification_quote='Furthermore, attention should be paid to § 13 Para. 4 of the Drinking Water Ordinance (TrinkwV), which implies that owners of rainwater and greywater treatment/reuse systems are obliged to notify the health authority upon commissioning. If these systems are already in operation, notification should be made immediately. In addition, recommissioning of systems which have undergone constructional or operational changes or user/owner change as well as system shutdown are also notifiable. — printed p.14', verification_note='md-verified 2026-09-05 (§4.4 (TrinkwV § 13 Para. 4), printed p.14 derived) [VC] — same-worksheet duplicate of authority_notification_sent (ws 24) — STAGED S-9 proposes active=false', verified_at=now() where id='54934511-c58f-494e-943c-2cb4284acd50' and verification_status not in ('verified_against_standard','corrected');
-- ifsg_pathogen_risk_addressed
update public.fields set verification_status='verified_against_standard', verification_quote='Water for human consumption as well as swimming and bathing pool water are governed by the criteria laid down in Section 7 (Water) § 37 Para. 1 of the Infection Protection Act (IfSG 2000). They must be provided in a quality such that, there is no concern of damage to human health from their use, particularly through pathogens. | In public and commercial buildings and there, where several households are connected to a greywater reuse system, treatment of the greywater depending on the intended use and the corresponding quality requirements, is indispensable. For the private sector, appropriate treatment processes should also be provided for greywater reuse. Quality requirements for service water should be orientated towards the specific intended use. — printed p.14 / p.18', verification_note='md-verified 2026-09-05 (§4.5 (IfSG § 37 Para. 1); §6.1, printed p.14 / p.18 derived) [VC] — IfSG § 37 governs water for human consumption and bathing water; the guideline applies it to greywater reuse indirectly (§4.1 "arise indirectly")', verified_at=now() where id='ffe18d9b-158a-4756-b2a3-75f4c5d021d2' and verification_status not in ('verified_against_standard','corrected');
-- machinery_directive_conformity
update public.fields set verification_status='verified_against_standard', verification_quote='To generate a conformity certificate and a CE-label, further requirements which arise from other European rules and standards such as the Machinery Directive (Directive 2006/42/EG), the Low-Voltage Directive (Directive 2014/35/EU) or the EMC Directive (Directive 2014/30/EU) (electromagnetic compatibility) must be identified and implemented. — printed p.13', verification_note='md-verified 2026-09-05 (§4.1 General, printed p.13 derived) [VC] — clause_reference reads "§4" — the sentence is §4.1 — STAGED S-7 retag; "must be identified and implemented" for a conformity certificate/CE-label', verified_at=now() where id='731d5481-ca69-431d-bf49-dab75df93118' and verification_status not in ('verified_against_standard','corrected');

